-- Aquagram — 0041: Altum ve Leopoldi melek, L-numara plekolar
on conflict (slug) do nothing;

-- L260 Queen Arabesque Tapajós kökenlidir (Xingu değil); L201 adı netleştirildi
update public.species set facts = (select jsonb_agg(case when f->>0='Köken' then '["Köken","Brezilya, Rio Tapajós"]'::jsonb else f end) from jsonb_array_elements(facts) f) where slug='hypancistrus-sp-l260';
update public.species set name='Orinoco Angel L201', keywords = array['orinoco angel l201','hypancistrus contradens','l201','orinoco angel pleco','pleco','vatoz'] where slug='hypancistrus-contradens';
