insert into public.species (slug,name,latin,category_id,kind,difficulty,temperament,description,facts,keywords,is_rare,care_notice,status) values
('pterophyllum-altum','Altum Melek','Pterophyllum altum','guney-amerika','fish','Zor','Barışçıl, grup halinde','Melek balıklarının en yüksek gövdelisidir; Orinoko ve yukarı Rio Negro''nun yumuşak, asidik kara sularından gelir. Derin bir tank, çok temiz yumuşak su ve sakin tank arkadaşları ister.','[["Yetişkin boy", "Yükseklik 30–40 cm (yüzgeçlerle)"], ["Sıcaklık", "28–31 °C"], ["pH", "4.5–6.5"], ["Min. akvaryum", "400 L (yükseklik en az 60 cm)"], ["Huy", "Barışçıl, grup halinde"], ["Beslenme", "Omnivor; canlı ve donmuş yem ağırlıklı"], ["Üreme", "Substrat yumurtlayıcı (akvaryumda zor)"], ["Köken", "Orinoko havzası (Atabapo, Inírida) ve yukarı Rio Negro"], ["Ömür", "10+ yıl"], ["Özellikler", "Nadir Tür"]]'::jsonb,array['altum melek','pterophyllum altum','altum','orinoco altum','altum angelfish','melek balığı','melekler','pterophyllum']::text[],true,'Yeni ithal edilen bireyler hastalığa ve strese çok yatkındır; karantina ve kusursuz su kalitesi şart.','published'),
('pterophyllum-leopoldi','Leopoldi Melek','Pterophyllum leopoldi','guney-amerika','fish','Orta','Yarı agresif','Üç melek türünün en küçüğüdür; sırt yüzgecinin önündeki koyu leke ile tanınır. Küçük boyu sayesinde orta boy, yüksek tanklarda da rahat eder.','[["Yetişkin boy", "Yükseklik 12–15 cm"], ["Sıcaklık", "26–30 °C"], ["pH", "5.5–7.0"], ["Min. akvaryum", "200 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Substrat yumurtlayıcı"], ["Köken", "Brezilya, Orta Amazon (Solimões–Amazonas)"], ["Ömür", "8–10 yıl"], ["Özellikler", "Nadir Tür"]]'::jsonb,array['leopoldi melek','pterophyllum leopoldi','leopoldi','teardrop angelfish','melek balığı','melekler','pterophyllum']::text[],true,null,'published'),
('hypancistrus-seideli','King Tiger Pleco L066','Hypancistrus seideli','kedi-baliklari','fish','Orta','Barışçıl, bölgeci','Siyah zemin üzerindeki krem-sarı kaplan çizgileriyle en sevilen Hypancistrus''lardan biridir; desen bireyden bireye çok değişir. Hypancistrus türleri sıcak, bol oksijenli ve akıntılı su sever; protein ağırlıklı beslenir ve mağaralarda ürer.','[["Yetişkin boy", "12 cm"], ["Sıcaklık", "27–30 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "120 L"], ["Huy", "Barışçıl, bölgeci"], ["Beslenme", "Omnivor, protein ağırlıklı"], ["Üreme", "Mağara yumurtacısı"], ["Köken", "Brezilya, Rio Xingu"], ["Ömür", "10+ yıl"], ["Özellikler", "L066"]]'::jsonb,array['king tiger pleco l066','hypancistrus seideli','l066','king tiger pleco','l66','kaplan vatoz','pleco','vatoz']::text[],false,null,'published'),
('hypancistrus-sp-l333','Yellow King Tiger L333','Hypancistrus sp. L333','kedi-baliklari','fish','Orta','Barışçıl, bölgeci','L066''nın sarı tonlu akrabasıdır; gençlerde parlak sarı-siyah desen, yaşla birlikte daha karmaşık bir labirent desenine dönüşür. Hypancistrus türleri sıcak, bol oksijenli ve akıntılı su sever; protein ağırlıklı beslenir ve mağaralarda ürer.','[["Yetişkin boy", "14 cm"], ["Sıcaklık", "27–30 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "150 L"], ["Huy", "Barışçıl, bölgeci"], ["Beslenme", "Omnivor, protein ağırlıklı"], ["Üreme", "Mağara yumurtacısı"], ["Köken", "Brezilya, Rio Xingu"], ["Ömür", "10+ yıl"], ["Özellikler", "L333, Nadir Tür"]]'::jsonb,array['yellow king tiger l333','hypancistrus sp. l333','l333','yellow king tiger','l333 pleco','hypancistrus l333','pleco','vatoz']::text[],true,null,'published'),
('hypancistrus-debilittera','Colombian Zebra L129','Hypancistrus debilittera','kedi-baliklari','fish','Orta','Barışçıl, bölgeci','Koyu zemin üzerindeki ince açık çizgileriyle zebra plekoyu andırır ama daha küçük ve daha dayanıklıdır. Hypancistrus türleri sıcak, bol oksijenli ve akıntılı su sever; protein ağırlıklı beslenir ve mağaralarda ürer.','[["Yetişkin boy", "10 cm"], ["Sıcaklık", "25–29 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "100 L"], ["Huy", "Barışçıl, bölgeci"], ["Beslenme", "Omnivor, protein ağırlıklı"], ["Üreme", "Mağara yumurtacısı"], ["Köken", "Kolombiya–Venezuela, Orinoko havzası"], ["Ömür", "10+ yıl"], ["Özellikler", "L129, Nadir Tür"]]'::jsonb,array['colombian zebra l129','hypancistrus debilittera','l129','colombian zebra','l129 pleco','pleco','vatoz']::text[],true,null,'published'),
('hypancistrus-inspector','Snowball Pleco L102','Hypancistrus inspector','kedi-baliklari','fish','Orta','Barışçıl, bölgeci','Siyah gövdedeki beyaz-krem benekleriyle ''kartopu'' adını alır. Cinsinin en iri türlerinden biridir; bölgecidir, her bireye ayrı mağara gerekir. Hypancistrus türleri sıcak, bol oksijenli ve akıntılı su sever; protein ağırlıklı beslenir ve mağaralarda ürer.','[["Yetişkin boy", "15 cm"], ["Sıcaklık", "25–29 °C"], ["pH", "5.5–7.0"], ["Min. akvaryum", "150 L"], ["Huy", "Barışçıl, bölgeci"], ["Beslenme", "Omnivor, protein ağırlıklı"], ["Üreme", "Mağara yumurtacısı"], ["Köken", "Venezuela–Brezilya, yukarı Rio Negro ve Casiquiare"], ["Ömür", "10+ yıl"], ["Özellikler", "L102, Nadir Tür"]]'::jsonb,array['snowball pleco l102','hypancistrus inspector','l102','snowball pleco','kartopu vatoz','l102 pleco','pleco','vatoz']::text[],true,null,'published'),
('scobinancistrus-aureatus','Sunshine Pleco L014','Scobinancistrus aureatus','kedi-baliklari','fish','Zor','Bölgeci','Koyu gövde üzerindeki altın sarısı benekler ve turuncu-sarı yüzgeç kenarlarıyla çok gösterişlidir. Doğada salyangoz ve kabuklularla beslenir; iri boyutu ve bölgeciliği nedeniyle geniş tank ister.','[["Yetişkin boy", "30 cm"], ["Sıcaklık", "27–31 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "400 L"], ["Huy", "Bölgeci"], ["Beslenme", "Etçil ağırlıklı (salyangoz, kabuklu, donmuş yem)"], ["Üreme", "Mağara yumurtacısı"], ["Köken", "Brezilya, Rio Xingu"], ["Ömür", "10+ yıl"], ["Özellikler", "L014, Nadir Tür"]]'::jsonb,array['sunshine pleco l014','scobinancistrus aureatus','l014','sunshine pleco','l14','güneş vatoz','pleco','vatoz']::text[],true,null,'published'),
('pseudacanthicus-pirarara','Scarlet Pleco L025','Pseudacanthicus pirarara','kedi-baliklari','fish','Zor','Agresif, bölgeci','Dikenli gövdesi ve kırmızı-turuncu yüzgeçleriyle ''kaktüs plekoları''nın en ünlüsüdür. Etçildir, iri ve kavgacıdır; aynı tankta başka iri plekolarla sorun çıkarabilir.','[["Yetişkin boy", "40+ cm"], ["Sıcaklık", "26–30 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "600 L"], ["Huy", "Agresif, bölgeci"], ["Beslenme", "Etçil (karides, midye, balık eti)"], ["Üreme", "Mağara yumurtacısı"], ["Köken", "Brezilya, Rio Xingu"], ["Ömür", "10+ yıl"], ["Özellikler", "L025, Nadir Tür"]]'::jsonb,array['scarlet pleco l025','pseudacanthicus pirarara','l025','scarlet pleco','scarlet cactus pleco','kaktüs pleco','l25','pleco','vatoz']::text[],true,'Çok büyür ve diğer dip balıklarına karşı saldırgan olabilir; tank arkadaşları dikkatle seçilmeli.','published'),
('panaque-armbrusteri','Tapajós Royal Pleco L027','Panaque armbrusteri','kedi-baliklari','fish','Zor','Bölgeci','Royal Panaque grubunun Brezilya türüdür; koyu çizgili gövdesi ve kırmızı göz halkasıyla tanınır. Odunla beslenen bir türdür; tankta mutlaka yumuşak kök odun bulunmalıdır.','[["Yetişkin boy", "40 cm"], ["Sıcaklık", "26–30 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "500 L"], ["Huy", "Bölgeci"], ["Beslenme", "Odun ve bitkisel ağırlıklı"], ["Üreme", "Mağara yumurtacısı"], ["Köken", "Brezilya, Tapajós ve Tocantins–Araguaia havzaları"], ["Ömür", "10+ yıl"], ["Özellikler", "L027, Nadir Tür"]]'::jsonb,array['tapajós royal pleco l027','panaque armbrusteri','l027','royal pleco','royal panaque','l27','pleco','vatoz']::text[],true,'Çok miktarda odun talaşı ve dışkı üretir; güçlü filtre ve sık su değişimi gerekir.','published'),
('panaqolus-albivermis','Flash Pleco L204','Panaqolus albivermis','kedi-baliklari','fish','Orta','Barışçıl, bölgeci','Koyu gövde üzerindeki krem-beyaz kıvrımlı çizgiler ve yaşla belirginleşen turuncu-kırmızı kuyruk kenarıyla dikkat çeker. Küçük kalan bir odun yiyicidir.','[["Yetişkin boy", "13 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "100 L"], ["Huy", "Barışçıl, bölgeci"], ["Beslenme", "Odun ve bitkisel ağırlıklı"], ["Üreme", "Mağara yumurtacısı"], ["Köken", "Peru, Marañón ve Ucayali havzaları"], ["Ömür", "10+ yıl"], ["Özellikler", "L204"]]'::jsonb,array['flash pleco l204','panaqolus albivermis','l204','flash pleco','l204 pleco','pleco','vatoz']::text[],false,null,'published'),
('peckoltia-compta','Leopard Frog Pleco L134','Peckoltia compta','kedi-baliklari','fish','Orta','Barışçıl','Sarı-siyah bantlı, kurbağa desenini andıran gövdesiyle küçük ve gösterişli bir plekodur. Topluluk tanklarına uygun, uysal bir türdür.','[["Yetişkin boy", "10 cm"], ["Sıcaklık", "26–30 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "100 L"], ["Huy", "Barışçıl"], ["Beslenme", "Omnivor, protein ağırlıklı"], ["Üreme", "Mağara yumurtacısı"], ["Köken", "Brezilya, Rio Tapajós"], ["Ömür", "10+ yıl"], ["Özellikler", "L134"]]'::jsonb,array['leopard frog pleco l134','peckoltia compta','l134','leopard frog pleco','l134 pleco','pleco','vatoz']::text[],false,null,'published'),
('hemiancistrus-subviridis','Green Phantom Pleco L200','Hemiancistrus subviridis','kedi-baliklari','fish','Orta','Bölgeci','Yeşilimsi-zeytin gövdesi ve açık beneklerle kaplı görünümüyle ''yeşil hayalet'' diye anılır. Güçlü akıntı ve bol oksijen ister; yosun ve bitkisel yemle iyi beslenir.','[["Yetişkin boy", "15 cm"], ["Sıcaklık", "26–30 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "200 L"], ["Huy", "Bölgeci"], ["Beslenme", "Bitkisel ağırlıklı omnivor"], ["Üreme", "Mağara yumurtacısı"], ["Köken", "Venezuela, Orinoko havzası"], ["Ömür", "10+ yıl"], ["Özellikler", "L200, Nadir Tür"]]'::jsonb,array['green phantom pleco l200','hemiancistrus subviridis','l200','green phantom','yeşil hayalet vatoz','l200 pleco','pleco','vatoz']::text[],true,null,'published'),
('ancistrus-dolichopterus','Starlight Bristlenose L183','Ancistrus dolichopterus','kedi-baliklari','fish','Orta','Barışçıl','Siyah gövdesi üzerindeki küçük beyaz benekler ve beyaz yüzgeç kenarlarıyla ''yıldız ışığı'' adını alır. Bilinen Ancistrus''lara göre daha yumuşak ve asidik su ister.','[["Yetişkin boy", "13 cm"], ["Sıcaklık", "25–29 °C"], ["pH", "5.0–6.8"], ["Min. akvaryum", "100 L"], ["Huy", "Barışçıl"], ["Beslenme", "Bitkisel ağırlıklı omnivor + odun"], ["Üreme", "Mağara yumurtacısı"], ["Köken", "Brezilya, Rio Negro havzası"], ["Ömür", "10+ yıl"], ["Özellikler", "L183"]]'::jsonb,array['starlight bristlenose l183','ancistrus dolichopterus','l183','starlight bristlenose','starlight ancistrus','l183 pleco','pleco','vatoz']::text[],false,null,'published'),
('leporacanthicus-galaxias','Galaxy Pleco L007','Leporacanthicus galaxias','kedi-baliklari','fish','Zor','Bölgeci','Siyah gövdedeki beyaz-krem benekler ve tavşanı andıran ön dişleriyle tanınır. Salyangoz ve kabukluları kırarak yiyen etçil bir türdür.','[["Yetişkin boy", "25 cm"], ["Sıcaklık", "26–30 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "300 L"], ["Huy", "Bölgeci"], ["Beslenme", "Etçil (salyangoz, karides, midye)"], ["Üreme", "Mağara yumurtacısı"], ["Köken", "Brezilya, Tocantins ve aşağı Amazon (Pará)"], ["Ömür", "10+ yıl"], ["Özellikler", "L007, Nadir Tür"]]'::jsonb,array['galaxy pleco l007','leporacanthicus galaxias','l007','galaxy pleco','vampire pleco','l7','l029','pleco','vatoz']::text[],true,null,'published'),
('leporacanthicus-joselimai','Sultan Pleco L264','Leporacanthicus joselimai','kedi-baliklari','fish','Zor','Bölgeci','Koyu gövde üzerindeki iri beyaz benekler ve sarı-beyaz yüzgeç kenarlarıyla çarpıcı bir türdür. Etçildir, salyangoz ve kabuklularla beslenir.','[["Yetişkin boy", "18 cm"], ["Sıcaklık", "27–30 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "250 L"], ["Huy", "Bölgeci"], ["Beslenme", "Etçil (salyangoz, karides, midye)"], ["Üreme", "Mağara yumurtacısı"], ["Köken", "Brezilya, Rio Tapajós"], ["Ömür", "10+ yıl"], ["Özellikler", "L264, Nadir Tür"]]'::jsonb,array['sultan pleco l264','leporacanthicus joselimai','l264','sultan pleco','l264 pleco','pleco','vatoz']::text[],true,null,'published'),
('leporacanthicus-triactis','Three Beacon Pleco L091','Leporacanthicus triactis','kedi-baliklari','fish','Zor','Bölgeci','Sırt ve kuyruk yüzgecindeki turuncu kenarlar adını veren ''üç fener''i oluşturur. Akıntılı, oksijenli su ve etçil beslenme ister.','[["Yetişkin boy", "20 cm"], ["Sıcaklık", "25–29 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "250 L"], ["Huy", "Bölgeci"], ["Beslenme", "Etçil ağırlıklı"], ["Üreme", "Mağara yumurtacısı"], ["Köken", "Venezuela–Kolombiya, Orinoko havzası"], ["Ömür", "10+ yıl"], ["Özellikler", "L091, Nadir Tür"]]'::jsonb,array['three beacon pleco l091','leporacanthicus triactis','l091','three beacon pleco','l91','pleco','vatoz']::text[],true,null,'published'),
('acanthicus-adonis','Polka Dot Lyretail L155','Acanthicus adonis','kedi-baliklari','fish','Zor','Bölgeci, iri','Gençken siyah zemin üzerinde beyaz benekli ve lir kuyruklu çok çekici bir balıktır; ancak erişkinde 1 metreye yaklaşabilen dev bir türe dönüşür.','[["Yetişkin boy", "80–100 cm"], ["Sıcaklık", "25–30 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "2000 L"], ["Huy", "Bölgeci, iri"], ["Beslenme", "Omnivor (yem tableti, kabuklu, sebze)"], ["Üreme", "Mağara yumurtacısı"], ["Köken", "Brezilya, Rio Tocantins"], ["Ömür", "20+ yıl"], ["Özellikler", "L155, Nadir Tür"]]'::jsonb,array['polka dot lyretail l155','acanthicus adonis','l155','polka dot lyretail','adonis pleco','l155 pleco','pleco','vatoz']::text[],true,'Ev akvaryumları için çok büyür; yalnızca kamu akvaryumu ölçeğinde tank sağlayabilecek hobiciler almalı.','published'),
('pterygoplichthys-gibbiceps','Sailfin Pleco L083','Pterygoplichthys gibbiceps','kedi-baliklari','fish','Kolay','Barışçıl, iri','Yüksek yelken sırt yüzgeci ve kahverengi benekli gövdesiyle en yaygın iri plekolardandır. Dayanıklıdır ama hızla büyür ve çok atık üretir.','[["Yetişkin boy", "50 cm"], ["Sıcaklık", "24–30 °C"], ["pH", "6.0–8.0"], ["Min. akvaryum", "500 L"], ["Huy", "Barışçıl, iri"], ["Beslenme", "Bitkisel ağırlıklı omnivor"], ["Üreme", "Toprak oyuk yuvaya yumurtlar"], ["Köken", "Amazon ve Orinoko havzaları"], ["Ömür", "15–20 yıl"], ["Özellikler", "L083"]]'::jsonb,array['sailfin pleco l083','pterygoplichthys gibbiceps','l083','sailfin pleco','yelkenli vatoz','l165','pleco','vatoz']::text[],false,'Satışta küçük görünür ama 50 cm''yi bulur; asla doğaya ya da göletlere salınmamalı.','published'),
('pterygoplichthys-pardalis','Leopar Vatoz','Pterygoplichthys pardalis','kedi-baliklari','fish','Kolay','Barışçıl, iri','Mağazalarda ''çöpçü vatoz'' diye en sık satılan türdür. Çok dayanıklıdır, ancak hızla büyür ve ağır biyolojik yük oluşturur.','[["Yetişkin boy", "45 cm"], ["Sıcaklık", "23–30 °C"], ["pH", "6.5–8.0"], ["Min. akvaryum", "400 L"], ["Huy", "Barışçıl, iri"], ["Beslenme", "Bitkisel ağırlıklı omnivor"], ["Üreme", "Toprak oyuk yuvaya yumurtlar"], ["Köken", "Brezilya–Peru, aşağı ve orta Amazon"], ["Ömür", "15–20 yıl"]]'::jsonb,array['leopar vatoz','pterygoplichthys pardalis','çöpçü vatoz','çöpçü balığı','common pleco','amazon sailfin','leopar çöpçü','pleco','vatoz']::text[],false,'Doğaya salındığı birçok ülkede istilacı tür haline gelmiştir; büyüyen bireyler asla dere, göl ya da göletlere bırakılmamalı.','published'),
('baryancistrus-beggini','Blue Panaque L239','Baryancistrus beggini','kedi-baliklari','fish','Zor','Bölgeci','Gençken gece mavisi gövde ve beyaz yüzgeç kenarlarıyla çok çarpıcıdır; erişkinde renk koyulaşır. Güçlü akıntı ve bitkisel ağırlıklı beslenme ister.','[["Yetişkin boy", "15 cm"], ["Sıcaklık", "27–30 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "200 L"], ["Huy", "Bölgeci"], ["Beslenme", "Aufwuchs, bitkisel ağırlıklı omnivor"], ["Üreme", "Mağara yumurtacısı"], ["Köken", "Venezuela, Orinoko havzası"], ["Ömür", "10+ yıl"], ["Özellikler", "L239, Nadir Tür"]]'::jsonb,array['blue panaque l239','baryancistrus beggini','l239','blue panaque','blue phantom','l239 pleco','pleco','vatoz']::text[],true,null,'published'),
('pseudacanthicus-leopardus','Leopard Cactus Pleco L114','Pseudacanthicus leopardus','kedi-baliklari','fish','Zor','Bölgeci','Dikenli gövdesi, iri koyu benekleri ve turuncu yüzgeç kenarlarıyla gösterişli bir kaktüs plekosudur. Etçildir, bölgecidir ve geniş tank ister.','[["Yetişkin boy", "30 cm"], ["Sıcaklık", "26–30 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "400 L"], ["Huy", "Bölgeci"], ["Beslenme", "Etçil (karides, midye, balık eti)"], ["Üreme", "Mağara yumurtacısı"], ["Köken", "Guyana, Essequibo havzası (Rupununi)"], ["Ömür", "10+ yıl"], ["Özellikler", "L114, Nadir Tür"]]'::jsonb,array['leopard cactus pleco l114','pseudacanthicus leopardus','l114','leopard cactus pleco','kaktüs pleco','l114 pleco','pleco','vatoz']::text[],true,null,'published'),
('panaque-cochliodon','Blue Eyed Panaque','Panaque cochliodon','kedi-baliklari','fish','Zor','Bölgeci','Gri-yeşil gövdesi ve parlak mavi gözleriyle tanınan, odun yiyen bir panaque türüdür. Kolombiya''nın Magdalena havzasından gelir; doğal popülasyonları baskı altındadır.','[["Yetişkin boy", "30 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "6.5–7.5"], ["Min. akvaryum", "400 L"], ["Huy", "Bölgeci"], ["Beslenme", "Odun ve bitkisel ağırlıklı"], ["Üreme", "Mağara yumurtacısı"], ["Köken", "Kolombiya, Magdalena–Cauca havzası"], ["Ömür", "10+ yıl"], ["Özellikler", "Nadir Tür"]]'::jsonb,array['blue eyed panaque','panaque cochliodon','blue eyed pleco','blue eye panaque','mavi gözlü vatoz','pleco','vatoz']::text[],true,'Bol odun talaşı ve atık üretir; güçlü filtre ve sık su değişimi gerekir.','published')
